function creerSubject() {
  let subscribers = [];
  let isCompleted = false;

  function next(val) {
    if (isCompleted) return;
    subscribers.forEach(s => { if (s.next) s.next(val); });
  }

  function error(err) {
    if (isCompleted) return;
    isCompleted = true;
    subscribers.forEach(s => { if (s.error) s.error(err); });
    subscribers = [];
  }

  function complete() {
    if (isCompleted) return;
    isCompleted = true;
    subscribers.forEach(s => { if (s.complete) s.complete(); });
    subscribers = [];
  }

  function subscribe(observer) {
    subscribers.push(observer);
    return {
      unsubscribe() {
        const idx = subscribers.indexOf(observer);
        if (idx !== -1) subscribers.splice(idx, 1);
      }
    };
  }

  return { next, error, complete, subscribe };
}
```

