function memoiserAsync(fn) {
  const cache = new Map();
  return function (...args) {
    const key = JSON.stringify(args);
    if (cache.has(key)) {
      return cache.get(key);
    }
    const promise = fn.apply(this, args)
      .then(result => {
        cache.set(key, Promise.resolve(result));
        return result;
      })
      .catch(err => {
        cache.delete(key);
        throw err;
      });
    cache.set(key, promise);
    return promise;
  };
}
