function creerCircuitBreaker(fn, seuil, delaiResetMs) {
  let state = 'CLOSED';
  let failureCount = 0;
  let timer = null;

  return async function (...args) {
    if (state === 'OPEN') {
      return Promise.reject(new Error('Circuit breaker is OPEN'));
    }

    try {
      const result = await fn(...args);
      if (state === 'HALF_OPEN') {
        state = 'CLOSED';
        failureCount = 0;
      }
      return result;
    } catch (err) {
      failureCount++;
      if (failureCount >= seuil) {
        state = 'OPEN';
        timer = setTimeout(() => {
          state = 'HALF_OPEN';
          failureCount = 0;
          timer = null;
        }, delaiResetMs);
      }
      throw err;
    }
  };
}
